SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷83·晋少帝本纪·开运二年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/jiuwudaishi-083-945-january/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运二年正月，段落 jiu-wudaishi-205deb4a7860-p002018；已核上下文及传主，纸本及异文待核。", "id": "58659c8a-2ea0-5594-bf3f-81d582ec60ca"}, {"title": "旧五代史·卷95·皇甫遇传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/jiuwudaishi-095-huangfu-yu-battle/source.txt", "note": "《旧五代史》卷95·皇甫遇传，段落 jiu-wudaishi-205deb4a7860-p002313；已核上下文及传主，纸本及异文待核。", "id": "be003fd4-1ed9-5a86-ad1a-93aa18541cc8"}, {"title": "辽史·卷4·太宗本纪·会同八年正月", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/liaoshi-004-945-january/source.txt", "note": "《辽史》卷4·太宗本纪·会同八年正月，段落 liaoshi-7cd182a20e67-p000555；已核上下文及传主，纸本及异文待核。", "id": "5ebeddff-9267-5eee-93d4-344aeb91f651"}, {"title": "资治通鉴·卷284·开运二年正月（后续段落不在本批处理）", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/tongjian-284-945-january/source.txt", "note": "《资治通鉴》卷284·开运二年正月（后续段落不在本批处理），段落 zizhi-tongjian-a63549944a71-p003378；已核上下文及传主，纸本及异文待核。", "id": "ddb8024d-0bbc-52da-9f92-29f566603fcb"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "editio